CREATE COLUMN TABLE "TEST_AP"."OMAO" ("Code" NVARCHAR(20) NOT NULL , "Name" NVARCHAR(200), "URL" NCLOB MEMORY THRESHOLD 1000, "Type" NVARCHAR(1) DEFAULT 'M', "Provider" NVARCHAR(200), "ViewStyle" NVARCHAR(1) DEFAULT 'P', "LogonMethd" NVARCHAR(1) DEFAULT 'B', "LogonPyld" NVARCHAR(254) DEFAULT 'user={value1}&pwd={value2}', "Enable" NVARCHAR(1) DEFAULT 'Y', "System" NVARCHAR(1) DEFAULT 'N', "B1MobileAp" NVARCHAR(1) DEFAULT 'N', "B1SalesApp" NVARCHAR(1) DEFAULT 'N', "B1SrvcApp" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE 